package com.slotmind.service;
import com.slotmind.dto.Dtos.*; import com.slotmind.entity.*; import com.slotmind.enums.*; import com.slotmind.exception.ApiExceptions.*; import com.slotmind.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class AppointmentService { final AppointmentRepository ar; final ProviderRepository pr; final SlotRepository sr; final SchedulingService ss; public AppointmentService(AppointmentRepository a,ProviderRepository p,SlotRepository s,SchedulingService x){ar=a;pr=p;sr=s;ss=x;} @Transactional public Appointment create(CreateAppointment r){Provider p=pr.findById(r.providerId()).orElseThrow(()->new NotFound("Provider not found"));Slot s=sr.lockById(r.slotId()).orElseThrow(()->new NotFound("Slot not found"));if(s.getStatus()!=SlotStatus.OPEN)throw new Conflict("Slot is not open");if(!s.getProvider().getId().equals(p.getId()))throw new Conflict("Slot does not belong to provider");if(p.getStatus()==ProviderStatus.OFFLINE)throw new Conflict("Provider is offline");s.setStatus(SlotStatus.BOOKED);Instant n=Instant.now();return ar.save(new Appointment("APT-"+UUID.randomUUID().toString().substring(0,8),r.patientName(),r.type(),p,s,AppointmentStatus.CONFIRMED,n,n,0));} public Appointment findById(String id){return ar.findById(id).orElseThrow(()->new NotFound("Appointment not found"));} public List<Appointment> list(AppointmentStatus status){return status==null?ar.findAll():ar.findByStatus(status);} }